(1, 'ddddddddd', 'sssssssssssssss', NULL, 'sssssssssssssssssssssssssssssssss', NULL, 1, 20, 1, 0, 'published', 'inactive', '8989', 'i988', 'iuui', '2026-02-19 03:39:59', '2026-02-19 03:39:59', '2026-02-19 03:39:59'),
(3, 'Top 10 Digital Marketing Trends in 2026', 'top-10-digital-marketing-trends-in-2026', NULL, 'digital marketing, marketing trends 2026, AI marketing, video marketing, SEO trends', NULL, 1, 20, 1, 0, 'published', 'active', 'Top Digital Marketing Trends in 2026', 'Explore the top digital marketing trends in 2026 including AI marketing, video marketing, and voice search optimization.', 'digital marketing, marketing trends 2026, AI marketing, video marketing, SEO trends', '2026-02-19 03:53:13', '2026-02-19 03:53:13', '2026-02-19 03:53:13'),
(4, 'Top Digital Marketing Trends in 2026', 'top-digital-marketing-trends-in-2026', NULL, 'Digital marketing is evolving faster than ever before. In 2026, businesses must adapt to new technologies and customer behaviors to stay competitive in the online marketplace.\r\n\r\nArtificial Intelligence is playing a huge role in marketing automation. From AI-powered chatbots to automated email marketing, businesses can now interact with customers in real time. Voice search optimization is also becoming important as more people use smart devices.\r\n\r\nVideo marketing continues to dominate social media platforms. Short-form videos on platforms like Instagram Reels and YouTube Shorts are helping brands reach wider audiences. Personalized marketing is another trend that is reshaping how companies communicate with customers.\r\n\r\nData-driven marketing strategies are allowing businesses to make better decisions. Understanding customer behavior through analytics helps in creating targeted campaigns.\r\n\r\nAdopting these digital marketing trends can help businesses increase engagement, improve brand visibility, and drive higher conversion rates.', NULL, 1, 21, 1, 0, 'published', 'active', 'Top Digital Marketing Trends in 2026', 'Explore the top digital marketing trends in 2026 including AI marketing, video marketing, and voice search optimization.', 'digital marketing, marketing trends 2026, AI marketing, video marketing, SEO trends', '2026-02-19 03:54:26', '2026-02-19 03:54:26', '2026-02-19 03:54:26'),
(5, 'Top 10 Digital Marketing Trends in 2026', 'top-10-digital-marketing-trends-in-2026-1', NULL, 'digital marketing, marketing trends 2026, AI marketing, video marketing, SEO trends', NULL, 1, 20, 1, 0, 'published', 'inactive', 'Top Digital Marketing Trends in 2026', 'Digital marketing is evolving faster than ever before. In 2026, businesses must adapt to new technologies and customer behaviors to stay competitive in the onli', 'Top Digital Marketing Trends in 2026', '2026-02-19 03:56:00', '2026-02-19 03:56:00', '2026-02-19 03:56:00');


